using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;using System.Web.Script.Serialization;
public sealed class ArchivePreview:UserControl {
 readonly string root;readonly Action back;Dictionary<string,object>lastResult;string lastPreview;readonly Button differences=new Button{Name="ShowArchiveDifferences",Text="Различия с рабочим набором — без слияния",AutoSize=true,Enabled=false};readonly Button returnCards=new Button{Name="ReturnArchiveCards",Text="Карточки архива",AutoSize=true,Enabled=false};readonly TextBox path=new TextBox{Name="ResearchArchivePath",Width=650};readonly Label status=new Label{Name="ArchivePreviewStatus",Dock=DockStyle.Top,Height=95};readonly Panel body=new Panel{Dock=DockStyle.Fill};
 public ArchivePreview(string root,Action back){this.root=root;this.back=back;Dock=DockStyle.Fill;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};var close=new Button{Text="Назад в Research",AutoSize=true};close.Click+=(s,e)=>back();var browse=new Button{Text="Выбрать локальный ZIP",AutoSize=true};browse.Click+=(s,e)=>{using(var dialog=new OpenFileDialog{Filter="RevEng research data ZIP|*.zip",CheckFileExists=true,Multiselect=false,InitialDirectory=Path.Combine(root,"exports")})if(dialog.ShowDialog(FindForm())==DialogResult.OK)path.Text=dialog.FileName;};var view=new Button{Name="VerifyResearchArchive",Text="Проверить и открыть отдельную копию данных",AutoSize=true};view.Click+=(s,e)=>Open();bar.Controls.Add(close);bar.Controls.Add(path);bar.Controls.Add(browse);bar.Controls.Add(view);differences.Click+=(s,e)=>ShowDifferences();returnCards.Click+=(s,e)=>ShowCards();bar.Controls.Add(differences);bar.Controls.Add(returnCards);Controls.Add(body);Controls.Add(status);Controls.Add(bar);status.Text="Архив исследовательских данных открывается в отдельной проверенной копии. Рабочие карточки, решения и сценарии не заменяются. Код из ZIP не загружается; источники не обновляются. Это не полный backup приложения и не импорт поверх текущих данных.";}
 void Clear(){foreach(Control c in body.Controls.Cast<Control>().ToArray())c.Dispose();body.Controls.Clear();}
 void ShowCards(){if(lastPreview==null)return;Clear();body.Controls.Add(new EvidenceComparison(lastPreview,back,root,true));}
 void ShowDifferences(){if(lastResult==null)return;Clear();var text=new RichTextBox{Name="ArchiveDifferenceDetail",ReadOnly=true,Dock=DockStyle.Fill,DetectUrls=false};var value=lastResult.ContainsKey("differences")?lastResult["differences"]:null;text.Text="Различия содержимого, не выбор лучшей идеи и не слияние. Один ID с разным содержимым требует явного решения человека. Даты и старые баллы не определяют победителя. Рабочие записи не заменены.\r\n\r\n"+new JavaScriptSerializer{MaxJsonLength=8388608}.Serialize(value);body.Controls.Add(text);}
 void Open(){try{if(String.IsNullOrWhiteSpace(path.Text))throw new InvalidOperationException("Сначала выберите локальный архив.");string issue;string python=PortableRuntime.Python(root,"export",out issue);if(python==null)throw new InvalidOperationException(issue);string raw=PortableRuntime.Run(python,PortableRuntime.Quote(Path.Combine(root,"archive_preview.py"))+" --root "+PortableRuntime.Quote(root)+" --archive "+PortableRuntime.Quote(path.Text),root,30000);var result=new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Deserialize<Dictionary<string,object>>(raw);if(Convert.ToString(result["status"])!="VERIFIED_ISOLATED_ARCHIVE_PREVIEW"||!Object.Equals(result["workspace_replaced"],false)||!Object.Equals(result["code_imported_from_archive"],false))throw new InvalidOperationException("Проверенная копия не подтверждена.");string preview=Path.GetFullPath(Convert.ToString(result["preview_root"])),allowed=Path.GetFullPath(Path.Combine(root,"archive-previews"))+Path.DirectorySeparatorChar;if(!preview.StartsWith(allowed,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(preview).StartsWith("verified-",StringComparison.Ordinal))throw new InvalidOperationException("Копия вне разрешённого каталога.");lastResult=result;lastPreview=preview;differences.Enabled=returnCards.Enabled=true;ShowCards();status.Text=(result.ContainsKey("portable_source_evidence")?"Source evidence scope: "+new JavaScriptSerializer().Serialize(result["portable_source_evidence"])+"\r\n":"")+(result.ContainsKey("protected_decision_snapshot_present")&&Object.Equals(result["protected_decision_snapshot_present"],true)?"Архив содержит отдельную защищённую копию решений; она не сливается с primary автоматически. Сравните оба файла при конфликте.\r\n":"")+"Просмотр исторического архива, SHA256 "+result["archive_sha256"]+"\r\nПроверенная копия: "+preview+"\r\nТекущее рабочее состояние не заменено. Сохранённые даты, авторство и неизвестное не стали новыми фактами.";}catch(Exception ex){status.Text="Архив не открыт: "+ex.Message+". Рабочие данные не заменены; никакого импорта/исполнения нет.";}}
}
